mapper.select:
/* 일상 건강기록 목록 조회(최신 N건을 기록 시각 오름차순) */ SELECT T.DAILY_HLTH_RCD_SN , T.DAILY_RCD_IDCT_CD , T.RCD_NVL , T.CRSD_STTS_CD , C.COM_CD_NM AS CRSD_STTS_CD_NM , T.RCD_DT FROM ( SELECT R.DAILY_HLTH_RCD_SN , R.DAILY_RCD_IDCT_CD , R.RCD_NVL , R.CRSD_STTS_CD , R.RCD_DT FROM DAILY_HLTH_RCD R WHERE R.PET_SN = #{cond.petSn} AND R.DEL_YN = 'N'
AND R.DAILY_RCD_IDCT_CD = #{cond.dailyRcdIdctCd}
AND R.RCD_DT >= #{cond.fromYmd}
AND R.RCD_DT < DATE_ADD(#{cond.toYmd}, INTERVAL 1 DAY)
ORDER BY R.RCD_DT DESC, R.DAILY_HLTH_RCD_SN DESC
LIMIT #{cond.size}
) T LEFT JOIN COM_CD C ON C.COM_CD = T.CRSD_STTS_CD ORDER BY T.RCD_DT, T.DAILY_HLTH_RCD_SN

/* 반려동물의 최신 체중 기록 수치 조회 */
SELECT RCD_NVL
  FROM DAILY_HLTH_RCD
 WHERE PET_SN = #{petSn}
   AND DAILY_RCD_IDCT_CD = #{weightCd}
   AND DEL_YN = 'N'
 ORDER BY RCD_DT DESC, DAILY_HLTH_RCD_SN DESC
 LIMIT 1

/* 공통코드 그룹의 하위 코드 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM COM_CD C
         JOIN COM_CD G
           ON G.COM_CD_SN = C.COM_CD_PRNT_SN
        WHERE G.COM_CD = #{prntComCd}
          AND G.COM_CD_PRNT_SN IS NULL
          AND C.COM_CD = #{comCd}
          AND C.USE_YN = 'Y'
       )

mapper.insert:
/* 일상 건강기록 등록 */
INSERT INTO DAILY_HLTH_RCD
     ( PET_SN
     , DAILY_RCD_IDCT_CD
     , CRSD_STTS_CD
     , RCD_NVL
     , RCD_DT
     , DEL_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{petSn}
     , #{dailyRcdIdctCd}
     , #{crsdSttsCd}
     , #{rcdNvl}
     , #{rcdDt}
     , 'N'
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 일상 건강기록 수정 */
UPDATE DAILY_HLTH_RCD
   SET CRSD_STTS_CD = #{record.crsdSttsCd}
     , RCD_NVL      = #{record.rcdNvl}
     , RCD_DT       = #{record.rcdDt}
     , MDFR_ID      = #{actorId}
     , MDFCN_DT     = NOW()
 WHERE DAILY_HLTH_RCD_SN = #{record.dailyHlthRcdSn}
   AND DEL_YN = 'N'

/* 일상 건강기록 삭제 */
UPDATE DAILY_HLTH_RCD
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE DAILY_HLTH_RCD_SN = #{dailyHlthRcdSn}
   AND DEL_YN = 'N'

/* 반려동물의 일상 건강기록 전체 삭제 (반려동물 삭제) */
UPDATE DAILY_HLTH_RCD
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'
